import sqlite3, collections
db=sqlite3.connect("file:/Users/jbotts/frus-analysis/c3/frus-copy-2026-10-25.db?mode=ro",uri=True)
db.execute("create temp table setA(volume_id text, document_id text)")
db.executemany("insert into setA values(?,?)",[tuple(l.rstrip("\n").split("\t")[:2]) for l in open("setA.tsv")])
print("setA rows",db.execute("select count(*) from setA").fetchone())
print("--- CAME-FROM (document_sources) Set A: citation_era")
for r in db.execute("select s.citation_era,count(*) from document_sources s join setA a on a.volume_id=s.volume_id and a.document_id=s.document_id group by 1 order by 2 desc"): print(r)
print("docs in setA with a document_sources row:",db.execute("select count(*) from document_sources s join setA a on a.volume_id=s.volume_id and a.document_id=s.document_id").fetchone())
print("--- CAME-FROM top (repository, record_group, lot_file_norm, series_name)")
for r in db.execute("select s.repository,s.record_group,s.lot_file_norm,substr(s.series_name,1,60),count(*) n from document_sources s join setA a on a.volume_id=s.volume_id and a.document_id=s.document_id group by 1,2,3,4 order by n desc limit 40"): print(r)
print("--- POINTED-AT (external_citations) Set A: anchor kinds")
for r in db.execute("select e.anchor,count(*),count(distinct e.volume_id||'/'||e.document_id) from external_citations e join setA a on a.volume_id=e.volume_id and a.document_id=e.document_id group by 1 order by 2 desc"): print(r)
print("--- POINTED-AT top lots")
for r in db.execute("select e.lot_file_norm,substr(e.collection,1,60),count(*) n,count(distinct e.volume_id||'/'||e.document_id) docs from external_citations e join setA a on a.volume_id=e.volume_id and a.document_id=e.document_id where e.lot_file_norm is not null group by 1,2 order by n desc limit 40"): print(r)
